// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LiquidityPool} from "../src/LiquidityPool.sol";

contract InvMutTest is Test {
    LiquidityPool c;
    __InvMutShare share;

    function setUp() public {
        share = new __InvMutShare();
        c = new LiquidityPool(0, bytes16(0), address(this), address(share), address(new __InvMutHandleStub()));
    }

    function testFuzz_property(uint256 amount, address from, address to, bool underlyingSaysTrue) public {
        vm.assume(amount < type(uint256).max);
        // the underlying share token is the adversarial counterparty: it may return false
        share.setReturn(underlyingSaysTrue);
        vm.prank(address(this));
        bool returned = c.transferFrom(from, to, amount);
        // rule: c's returned value must equal the value the share token actually returned
        assertTrue(returned == share.lastReturn());
    }
}

contract __InvMutShare {
    bool private _ret;
    bool public lastReturn;

    function setReturn(bool r) external { _ret = r; }

    function transferFrom(address, address, uint256) external returns (bool) {
        lastReturn = _ret;
        return _ret;
    }

    function name() external pure returns (string memory) { return "S"; }
    function symbol() external pure returns (string memory) { return "S"; }
    function decimals() external pure returns (uint8) { return 18; }
    function totalSupply() external pure returns (uint256) { return 0; }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function allowance(address, address) external pure returns (uint256) { return 0; }
    function checkTransferRestriction(address, address, uint256) external pure returns (bool) { return true; }
    receive() external payable {}
    fallback() external payable {}
}

